CREATE OR REPLACE FUNCTION lms.is_active_app_user(user_id UUID DEFAULT auth.uid())
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = lms
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM lms.users
    WHERE id = user_id
      AND is_active = TRUE
      AND deleted_at IS NULL
  );
$$;

