-- User-controlled auth metadata must not grant application roles.
CREATE OR REPLACE FUNCTION lms.handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
BEGIN
  IF NEW.email IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.email_confirmed_at IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO lms.users (id, email, full_name, role)
  VALUES (
    NEW.id,
    NEW.email,
    NULLIF(BTRIM(COALESCE(NEW.raw_user_meta_data->>'full_name', '')), ''),
    'learner'
  )
  ON CONFLICT (id) DO UPDATE
    SET email = EXCLUDED.email,
        full_name = COALESCE(lms.users.full_name, EXCLUDED.full_name);

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'handle_new_user failed for user %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

DROP POLICY IF EXISTS "users: read own" ON lms.users;
CREATE POLICY "users: read own" ON lms.users
  FOR SELECT
  USING (auth.uid() = id AND lms.is_active_app_user(auth.uid()));

DROP POLICY IF EXISTS "users: admin read all" ON lms.users;
CREATE POLICY "users: admin read all" ON lms.users
  FOR SELECT
  USING (lms.is_admin());

DROP POLICY IF EXISTS "users: admin update" ON lms.users;
CREATE POLICY "users: admin update" ON lms.users
  FOR UPDATE
  USING (lms.is_admin())
  WITH CHECK (lms.is_admin());

DROP POLICY IF EXISTS "users: self update non-sensitive" ON lms.users;
CREATE POLICY "users: self update safe profile fields" ON lms.users
  FOR UPDATE
  USING (auth.uid() = id AND lms.is_active_app_user(auth.uid()))
  WITH CHECK (auth.uid() = id AND lms.is_active_app_user(auth.uid()));

-- RLS decides which rows can be updated; column grants decide which fields.
REVOKE UPDATE ON lms.users FROM anon;
REVOKE UPDATE ON lms.users FROM authenticated;
GRANT UPDATE (full_name, phone, avatar_url) ON lms.users TO authenticated;

-- Keep inactive/deleted actors out of core policies.
DROP POLICY IF EXISTS "users: teacher read assigned" ON lms.users;
CREATE POLICY "users: teacher read assigned" ON lms.users
  FOR SELECT
  USING (
    lms.is_teacher()
    AND is_active = TRUE
    AND deleted_at IS NULL
    AND EXISTS (
      SELECT 1
      FROM lms.teacher_assignments
      WHERE teacher_id = auth.uid()
        AND learner_id = users.id
        AND is_active = TRUE
    )
  );

DROP POLICY IF EXISTS "modules: read published" ON lms.modules;
CREATE POLICY "modules: read published" ON lms.modules
  FOR SELECT
  USING (
    auth.uid() IS NOT NULL
    AND lms.is_active_app_user(auth.uid())
    AND is_published = TRUE
    AND deleted_at IS NULL
  );

DROP POLICY IF EXISTS "progress: learner own" ON lms.learner_progress;
CREATE POLICY "progress: learner own" ON lms.learner_progress
  FOR SELECT
  USING (learner_id = auth.uid() AND lms.is_active_app_user(auth.uid()));

DROP POLICY IF EXISTS "progress: teacher assigned" ON lms.learner_progress;
CREATE POLICY "progress: teacher assigned" ON lms.learner_progress
  FOR SELECT
  USING (
    lms.is_teacher()
    AND EXISTS (
      SELECT 1
      FROM lms.teacher_assignments
      WHERE teacher_id = auth.uid()
        AND learner_id = learner_progress.learner_id
        AND is_active = TRUE
    )
  );

DROP POLICY IF EXISTS "progress: admin all" ON lms.learner_progress;
CREATE POLICY "progress: admin all" ON lms.learner_progress
  USING (lms.is_admin());

DROP POLICY IF EXISTS "activity_logs: user read own" ON lms.activity_logs;
CREATE POLICY "activity_logs: user read own" ON lms.activity_logs
  FOR SELECT
  USING (user_id = auth.uid() AND lms.is_active_app_user(auth.uid()));

DROP POLICY IF EXISTS "activity_logs: admin all" ON lms.activity_logs;
CREATE POLICY "activity_logs: admin all" ON lms.activity_logs
  USING (lms.is_admin());

DROP POLICY IF EXISTS "storage: authenticated read" ON storage.objects;
CREATE POLICY "storage: authenticated read"
  ON storage.objects
  FOR SELECT
  USING (bucket_id = 'study-notes' AND lms.is_active_app_user(auth.uid()));

DROP POLICY IF EXISTS "storage: admin write" ON storage.objects;
CREATE POLICY "storage: admin write"
  ON storage.objects
  FOR INSERT
  WITH CHECK (bucket_id = 'study-notes' AND lms.is_admin());

CREATE OR REPLACE FUNCTION lms.validate_teacher_reference()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
BEGIN
  IF TG_TABLE_NAME = 'teacher_assignments' THEN
    IF NOT EXISTS (
      SELECT 1 FROM lms.users
      WHERE id = NEW.teacher_id
        AND role = 'teacher'
        AND is_active = TRUE
        AND deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'teacher_assignments.teacher_id must reference an active teacher';
    END IF;
  ELSIF TG_TABLE_NAME = 'learner_progress' AND NEW.teacher_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM lms.users
      WHERE id = NEW.teacher_id
        AND role IN ('teacher', 'admin')
        AND is_active = TRUE
        AND deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'learner_progress.teacher_id must reference an active teacher/admin';
    END IF;
  ELSIF TG_TABLE_NAME = 'events' AND NEW.teacher_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM lms.users
      WHERE id = NEW.teacher_id
        AND role IN ('teacher', 'admin')
        AND is_active = TRUE
        AND deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'events.teacher_id must reference an active teacher/admin';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS validate_teacher_assignment_teacher ON lms.teacher_assignments;
CREATE TRIGGER validate_teacher_assignment_teacher
  BEFORE INSERT OR UPDATE OF teacher_id ON lms.teacher_assignments
  FOR EACH ROW EXECUTE PROCEDURE lms.validate_teacher_reference();

DROP TRIGGER IF EXISTS validate_learner_progress_teacher ON lms.learner_progress;
CREATE TRIGGER validate_learner_progress_teacher
  BEFORE INSERT OR UPDATE OF teacher_id ON lms.learner_progress
  FOR EACH ROW EXECUTE PROCEDURE lms.validate_teacher_reference();

DROP TRIGGER IF EXISTS validate_event_teacher ON lms.events;
CREATE TRIGGER validate_event_teacher
  BEFORE INSERT OR UPDATE OF teacher_id ON lms.events
  FOR EACH ROW EXECUTE PROCEDURE lms.validate_teacher_reference();
